package net.imadz.domain.invariants

import net.imadz.common.CommonTypes.{InvariantRule, iMadzError}
import net.imadz.domain.entities.CreditBalanceEntity.{BalanceChanged, CreditBalanceEvent, CreditBalanceState}
import net.imadz.domain.values.Money

object AddInitialOnlyOnceRule extends InvariantRule[CreditBalanceEvent, CreditBalanceState, Money] {

  private val InitialConditionNotMeet: iMadzError = iMadzError("60000", "不满足 Initial 条件")

  def apply(creditBalanceState: CreditBalanceState, initial: Money): Either[iMadzError, List[CreditBalanceEvent]] =
    if (creditBalanceState.accountBalance.values.exists(_.amount > 0)) Left(InitialConditionNotMeet)
    else Right(List(BalanceChanged(initial)))

}

package net.imadz.domain.invariants

import net.imadz.common.CommonTypes.{InvariantRule, iMadzError}
import net.imadz.domain.entities.CreditBalanceEntity.{BalanceChanged, CreditBalanceEvent, CreditBalanceState}
import net.imadz.domain.values.Money

object DepositRule extends InvariantRule[CreditBalanceEvent, CreditBalanceState, Money] {
  private val ChangeShouldBePositive: iMadzError = iMadzError("60001", "change 需要为正数")

  def apply(state: CreditBalanceState, change: Money): Either[iMadzError, List[CreditBalanceEvent]] =
    if (change.amount <= 0) Left(ChangeShouldBePositive)
    else Right(List(BalanceChanged(change)))
}

package net.imadz.domain.invariants

import net.imadz.common.CommonTypes.{InvariantRule, iMadzError}
import net.imadz.domain.entities.CreditBalanceEntity.{BalanceChanged, CreditBalanceEvent, CreditBalanceState}
import net.imadz.domain.values.Money

object WithdrawRule extends InvariantRule[CreditBalanceEvent, CreditBalanceState, Money] {

  private val NotEnoughBalance: iMadzError = iMadzError("60002", "balance 不足扣减 或 扣减值应该为正数")

  def apply(creditBalanceState: CreditBalanceState, withdrawAmount: Money): Either[iMadzError, List[CreditBalanceEvent]] =
    if (creditBalanceState.accountBalance
      .get(withdrawAmount.currency.getCurrencyCode)
      .flatMap(withdrawAmount <= _)
      .getOrElse(false)) Right(List(BalanceChanged(withdrawAmount.copy(amount = -withdrawAmount.amount))))
    else
      Left(NotEnoughBalance)

}

package net.imadz.domain.invariants

import net.imadz.common.CommonTypes.{InvariantRule, Id, iMadzError}
import net.imadz.domain.entities.CreditBalanceEntity.{CreditBalanceEvent, CreditBalanceState, FundsReserved}
import net.imadz.domain.services.TransferValidatorDomainService
import net.imadz.domain.values.Money

object ReserveFundsRule extends InvariantRule[CreditBalanceEvent, CreditBalanceState, (Id, Money)] {
  def apply(state: CreditBalanceState, param: (Id, Money)): Either[iMadzError, List[CreditBalanceEvent]] = {
    val (transferId, amount) = param
    val currentBalance = state.accountBalance.getOrElse(amount.currency.getCurrencyCode, Money(BigDecimal(0), amount.currency))

    TransferValidatorDomainService.validate(transferId, state.reservedAmount, Some(currentBalance), amount) match {
      case Right(_) =>
        Right(List(FundsReserved(transferId, amount)))

      // [Magic] 原逻辑中 60008 表示"已存在/幂等"，此时回复成功但不做操作
      // 在 Rule 中，这对应于 Right(Nil) -> 无事件产生
      case Left(err) if err.code == "60008" =>
        Right(Nil)

      case Left(error) =>
        Left(error)
    }
  }
}

package net.imadz.domain.invariants

import net.imadz.common.CommonTypes.{InvariantRule, Id, iMadzError}
import net.imadz.domain.entities.CreditBalanceEntity._

object DeductFundsRule extends InvariantRule[CreditBalanceEvent, CreditBalanceState, Id] {
  def apply(state: CreditBalanceState, transferId: Id): Either[iMadzError, List[CreditBalanceEvent]] = {
    state.reservedAmount.get(transferId) match {
      case Some(reservedAmount) =>
        Right(List(FundsDeducted(transferId, reservedAmount)))
      case None =>
        Left(iMadzError("60006", "No reserved funds found for this transfer"))
    }
  }
}

