package net.imadz.domain.invariants

import net.imadz.common.CommonTypes.{InvariantRule, Id, iMadzError}
import net.imadz.domain.entities.CreditBalanceEntity.{CreditBalanceEvent, CreditBalanceState, IncomingCreditsRecorded}
import net.imadz.domain.values.Money

object RecordIncomingCreditsRule extends InvariantRule[CreditBalanceEvent, CreditBalanceState, (Id, Money)] {
  def apply(state: CreditBalanceState, param: (Id, Money)): Either[iMadzError, List[CreditBalanceEvent]] = {
    val (transferId, amount) = param
    state.incomingCredits.get(transferId) match {
      case Some(_) => Left(iMadzError("60007", "incoming credits already registered"))
      case None => Right(List(IncomingCreditsRecorded(transferId, amount)))
    }
  }
}

package net.imadz.domain.invariants

import net.imadz.common.CommonTypes.{InvariantRule, Id, iMadzError}
import net.imadz.domain.entities.CreditBalanceEntity.{CreditBalanceEvent, CreditBalanceState, IncomingCreditsCommited}

object CommitIncomingCreditsRule extends InvariantRule[CreditBalanceEvent, CreditBalanceState, Id] {
  def apply(state: CreditBalanceState, transferId: Id): Either[iMadzError, List[CreditBalanceEvent]] = {
    state.incomingCredits.get(transferId) match {
      case Some(_) => Right(List(IncomingCreditsCommited(transferId)))
      case None => Left(iMadzError("60008", "incoming credits cannot be found or already be committed before"))
    }
  }
}

package net.imadz.domain.invariants

import net.imadz.common.CommonTypes.{InvariantRule, Id, iMadzError}
import net.imadz.domain.entities.CreditBalanceEntity.{CreditBalanceEvent, CreditBalanceState, IncomingCreditsCanceled}

object CancelIncomingCreditRule extends InvariantRule[CreditBalanceEvent, CreditBalanceState, Id] {
  def apply(state: CreditBalanceState, transferId: Id): Either[iMadzError, List[CreditBalanceEvent]] = {
    state.incomingCredits.get(transferId) match {
      case Some(_) => Right(List(IncomingCreditsCanceled(transferId)))
      case None => Left(iMadzError("60009", "incoming credits cannot be found or already be canceled before"))
    }
  }
}
